# Previously generated by GoReleaser. Now maintained by hand: releases are built
# and published locally, so nothing regenerates this file. Update version and the
# four sha256 values on each release.
#
# Note: the macOS stanza is per-architecture. It previously pointed at
# ntm_<version>_darwin_all.tar.gz, a universal binary that recent releases have
# not shipped, so the cask was broken for every version after 1.18.3.
cask "ntm" do
  version "1.22.0"

  on_macos do
    on_intel do
      sha256 "2d0f7e4b68c34670599d80f59a498baf17ca0213169a17dd14af7bf6542a8231"
      url "https://github.com/Dicklesworthstone/ntm/releases/download/v#{version}/ntm_#{version}_darwin_amd64.tar.gz"
    end
    on_arm do
      sha256 "d40ee14f2c00d83b9db8ab17554e6ffdc678688d4a5defdf44ba55577ddc936c"
      url "https://github.com/Dicklesworthstone/ntm/releases/download/v#{version}/ntm_#{version}_darwin_arm64.tar.gz"
    end
  end

  on_linux do
    on_intel do
      sha256 "51a76b2546abf2a86785a3e51b2b6fbb04ccda91d4f08d0c3ad764387b364c87"
      url "https://github.com/Dicklesworthstone/ntm/releases/download/v#{version}/ntm_#{version}_linux_amd64.tar.gz"
    end
    on_arm do
      sha256 "6395b7e0d97bb6c562053d22ef0b91efaf7533161a4ae692a1adb6f1e2cdbdab"
      url "https://github.com/Dicklesworthstone/ntm/releases/download/v#{version}/ntm_#{version}_linux_arm64.tar.gz"
    end
  end

  name "ntm"
  desc "Named Tmux Manager - Orchestrate AI coding agents in tmux sessions"
  homepage "https://github.com/Dicklesworthstone/ntm"

  livecheck do
    skip "Updated manually on release."
  end
  depends_on formula: [
      "tmux",
    ]

  binary "ntm"

  # No zap stanza required

  caveats <<~EOS
    To complete installation, add the following to your shell config:

      # For zsh (add to ~/.zshrc):
      eval "$(ntm shell zsh)"

      # For bash (add to ~/.bashrc):
      eval "$(ntm shell bash)"

    Run 'ntm tutorial' to get started!
  EOS
end
